<?php
declare(strict_types=1);
session_start();
require_once dirname(__DIR__) . '/api/config.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
$products = db()->query('SELECT id, name, image, stock_quantity, low_stock_threshold FROM products ORDER BY stock_quantity ASC, name ASC')->fetchAll();
function inventoryEscape(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory - Electra admin</title><link rel="stylesheet" href="admin.css"><style>.inventory-table input{width:90px;padding:8px;border:1px solid var(--line);border-radius:5px}.inventory-table button{padding:8px 11px;border:0;border-radius:6px;background:#11100e;color:#e6cd93;font:700 11px inherit;cursor:pointer}.inventory-image{width:48px;height:48px;object-fit:cover;border-radius:6px}.stock-ok{color:#795722;font-weight:700}.stock-low{color:#a96c18;font-weight:700}.stock-out{color:#a33b30;font-weight:700}.saved{margin-bottom:18px;padding:12px;border:1px solid var(--gold);background:var(--gold-pale);color:#795722}</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">E</span><span>Electra</span></a><p class="nav-label">Store management</p><nav class="side-nav"><a href="index.php"><span>Overview</span></a><a href="products.php"><span>Products</span></a><a href="orders.php"><span>Orders</span></a><a href="payments.php"><span>Payments</span></a><a class="active" href="inventory.php"><span>Inventory</span></a></nav><p class="nav-label bottom-label">General</p><nav class="side-nav"><a href="index.php?view=settings"><span>Settings</span></a><a class="sign-out" href="logout.php"><span>Sign out</span></a></nav><div class="sidebar-foot"><i></i> Store online</div></aside><main class="workspace"><header class="workspace-header"><div><p class="kicker">Electra store</p><h1>Inventory</h1></div><div class="profile"><span class="avatar"><?= inventoryEscape(strtoupper(substr((string) $_SESSION['admin_name'], 0, 1))) ?></span><span><strong><?= inventoryEscape((string) $_SESSION['admin_name']) ?></strong><small>Store manager</small></span></div></header><?php if (isset($_GET['saved'])): ?><p class="saved">Inventory updated.</p><?php endif; ?><section class="page-heading"><div><p class="section-kicker">Stock control</p><h2>Inventory levels</h2><p>Out-of-stock products cannot be added to cart. Stock is deducted when payment is approved.</p></div></section><section class="card table-card"><div class="table-wrap"><table class="inventory-table"><thead><tr><th>Product</th><th>Stock</th><th>Low-stock alert at</th><th>Save</th></tr></thead><tbody><?php foreach ($products as $product): $stock=(int)$product['stock_quantity'];$threshold=(int)$product['low_stock_threshold'];$class=$stock===0?'stock-out':($stock<=$threshold?'stock-low':'stock-ok'); ?><tr><td><img class="inventory-image" src="../<?= inventoryEscape((string)$product['image']) ?>" alt=""><strong><?= inventoryEscape((string)$product['name']) ?></strong><small><?= inventoryEscape((string)$product['id']) ?></small></td><td class="<?= $class ?>"><?= $stock===0?'Out of stock':$stock.' available' ?></td><td><form method="post" action="inventory-actions.php"><input type="hidden" name="id" value="<?= inventoryEscape((string)$product['id']) ?>"><input type="number" name="stock_quantity" min="0" value="<?= $stock ?>" aria-label="Stock quantity for <?= inventoryEscape((string)$product['name']) ?>"><input type="number" name="low_stock_threshold" min="0" value="<?= $threshold ?>" aria-label="Low stock threshold for <?= inventoryEscape((string)$product['name']) ?>"></td><td><button type="submit">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></body></html>
